<template>
  <div
    :class="rootClass"
  >
    <input
      v-if="name"
      type="hidden"
      :name="name"
      :value="hiddenFieldValue"
    >
    <ui-popover
      v-model:open="menuOpen"
      placement="bottom-start"
      :match-trigger-width="matchTriggerWidth && !$slots.trigger"
      :width="width"
      :disabled="isDisabled"
      :align-selected-option-to-trigger="alignSelectedToTrigger"
    >
      <template #trigger="{ open, toggle, close }">
        <slot
          name="trigger"
          :open="open"
          :toggle="toggle"
          :close="close"
          :label="displayLabel"
          :has-value="!isPlaceholderDisplay"
        >
          <component
            :is="multiple ? 'div' : 'button'"
            class="ui-select-field"
            :class="{
              'ui-select-field--values': multiple,
              'ui-select-field--bare': variant === 'inline',
              'ui-select-field--disabled': multiple && isDisabled,
            }"
            v-bind="triggerAttrs(open)"
            @click="onTriggerClick(toggle)"
            @keydown="onTriggerKeydown($event, toggle)"
          >
            <span
              v-if="prefixIcon"
              class="ui-select-prefix inline-flex shrink-0 items-center text-muted-foreground"
              aria-hidden="true"
            >
              <ui-icon
                :name="prefixIcon"
                size="xs"
              />
            </span>
            <div
              v-if="multiple"
              class="ui-select-values-inner"
            >
              <Tag
                v-for="val in selectedValues"
                :key="String(val)"
                color="primary"
                variant="muted"
                size="sm"
                removable
                @remove="removeValue(val)"
              >
                {{ labelForValue(val) }}
              </Tag>
              <input
                v-if="isFilterable"
                ref="searchInput"
                v-model="filterQuery"
                type="text"
                class="ui-select-values-input"
                :class="{
                  'ui-select-values-input--solo': !selectedValues.length,
                  'ui-select-values-input--open': menuOpen,
                }"
                :placeholder="multipleInputPlaceholder"
                :id="resolvedId"
                role="combobox"
                :aria-label="resolvedFilterPlaceholder"
                aria-haspopup="listbox"
                :aria-expanded="menuOpen ? 'true' : 'false'"
                :aria-controls="menuOpen ? listboxId : undefined"
                :aria-activedescendant="menuOpen ? activeOptionId : undefined"
                :aria-describedby="formFieldDescribedBy(ariaDescribedby)"
                :aria-invalid="formFieldInvalid"
                autocomplete="off"
                :disabled="isDisabled"
                @click.stop="onSearchInputActivate"
                @focus="onSearchInputActivate"
                @keydown="onSearchKeydown"
              >
            </div>
            <span
              v-else-if="loading"
              class="ui-select-value ui-select-value--placeholder"
              data-popover-align
            >{{ resolvedLoadingLabel }}</span>
            <span
              v-else
              class="ui-select-value"
              :class="{ 'ui-select-value--placeholder': isPlaceholderDisplay }"
              v-bind="selectedDisplayStyle ? { style: selectedDisplayStyle } : {}"
              data-popover-align
            >{{ displayLabel }}</span>
            <span class="ui-select-field-suffix">
              <button
                v-if="showClearButton"
                type="button"
                class="ui-select-clear"
                :aria-label="clearAriaLabel"
                @click.stop="clearSelection"
              >
                <ui-icon
                  name="xmark"
                  size="xs"
                />
              </button>
              <span
                class="ui-select-chevron"
                aria-hidden="true"
              >
                <ui-icon
                  name="chevron-down"
                  size="xs"
                />
              </span>
            </span>
          </component>
        </slot>
      </template>
      <template
        v-if="showPopoverHeader"
        #header="{ close }"
      >
        <input
          ref="filterInput"
          v-model="filterQuery"
          type="text"
          class="ui-select-filter-input w-full"
          :class="filterInputClass"
          :data-size="resolvedSize"
          :placeholder="resolvedFilterPlaceholder"
          :aria-label="resolvedFilterPlaceholder"
          :aria-activedescendant="activeOptionId"
          :aria-controls="listboxId"
          autocomplete="off"
          @mousedown.prevent
          @keydown="onFilterKeydown($event, close)"
        >
      </template>
      <template #content="{ close }">
        <div
          ref="listbox"
          :id="listboxId"
          class="ui-select-listbox"
          :class="listboxClass"
          :data-size="resolvedSize"
          :role="listboxRole"
          :aria-multiselectable="multiple ? 'true' : undefined"
          :aria-labelledby="resolvedId"
        >
          <div
            v-if="loading && !filteredOptions.length"
            class="flex flex-col gap-2 px-1 py-2"
          >
            <ui-skeleton
              v-for="i in 3"
              :key="i"
              variant="line"
              :class="i === 3 ? 'max-w-[72%]' : undefined"
            />
          </div>
          <template v-else-if="filteredOptions.length">
            <ui-button
              v-for="(opt, i) in filteredOptions"
              :id="optionId(i)"
              :key="String(opt.value)"
              variant="ghost"
              color="secondary"
              :size="optionButtonSize"
              block
              text-align="left"
              role="option"
              class="ui-select-option"
              :class="{
                'ui-select-option--selected': isSelected(opt),
                'ui-select-option--active': i === activeIndex,
              }"
              :suffix-icon="isSelected(opt) ? 'check' : undefined"
              :aria-selected="isSelected(opt) ? 'true' : 'false'"
              tabindex="-1"
              @click="pick(opt, close)"
              @mousemove="activeIndex = i"
            >
              <slot
                name="option"
                :option="opt"
                :selected="isSelected(opt)"
              >
                <span class="flex w-full min-w-0 items-center justify-between gap-2">
                  <span
                    data-popover-align
                    class="min-w-0 truncate"
                    v-bind="optionDisplayStyle(opt) ? { style: optionDisplayStyle(opt) } : {}"
                  >{{ opt.label }}</span>
                  <ui-badge
                    v-if="opt.badge"
                    :color="opt.badgeColor || 'secondary'"
                    :variant="opt.badgeVariant || 'solid'"
                    size="xs"
                  >
                    {{ opt.badge }}
                  </ui-badge>
                  <span
                    v-else-if="opt.description"
                    class="shrink-0 text-muted-foreground"
                  >{{ opt.description }}</span>
                </span>
              </slot>
            </ui-button>
          </template>
          <ui-empty
            v-else-if="isFilterable && filterQuery"
            icon="magnifying-glass"
            :size="emptyStateSize"
            :title="noResultsText"
          />
          <ui-empty
            v-else
            icon="table-cells"
            :size="emptyStateSize"
            :title="emptyOptionsText"
          />
        </div>
      </template>
      <template
        v-if="$slots.footer"
        #footer="footerSlot"
      >
        <slot
          name="footer"
          v-bind="footerSlot"
        />
      </template>
    </ui-popover>
  </div>
</template>

<script>
import { cn } from '../utils/cn.js'
import { resolveThemeControlSize } from '../theme/resolve-theme-default.js'
import { createUiIdFactory } from '../utils/ui-id.js'
import Tag from './Tag.vue'
import { uiDefaultsMixin } from '../theme/ui-defaults.js'
import { CONTROL_SIZES } from '../utils/sizes.js'
import { formFieldMixin } from '../utils/form-field.js'

/** Reset via `resetUiIds()` — module counters drift on Cloudflare Worker isolates. */
const nextSelectId = createUiIdFactory('ui-select')

const VARIANTS = ['field', 'inline']
const SIZES = CONTROL_SIZES

export default {
  name: 'Select',
  mixins: [uiDefaultsMixin, formFieldMixin],
  components: { Tag },
  inheritAttrs: false,
  props: {
    variant: {
      type: String,
      default: 'field',
      validator: (v) => VARIANTS.includes(v),
    },
    size: {
      type: String,
      default: undefined,
      validator: (v) => v == null || SIZES.includes(v),
    },
    modelValue: {
      type: [String, Number, Boolean, Array],
      default: undefined,
    },
    /** Çoklu seçim — `modelValue` dizi; tetikleyicide etiketler + arama, listede onay işareti */
    multiple: {
      type: Boolean,
      default: false,
    },
    options: {
      type: Array,
      default: () => [],
    },
    disabled: {
      type: Boolean,
      default: false,
    },
    loading: {
      type: Boolean,
      default: false,
    },
    placeholder: {
      type: String,
      default: undefined,
    },
    clearable: {
      type: Boolean,
      default: false,
    },
    filterable: {
      type: Boolean,
      default: false,
    },
    filterPlaceholder: {
      type: String,
      default: '',
    },
    /** Tetikleyici sol ikon (`ui-icon` `name`) */
    prefixIcon: {
      type: String,
      default: null,
    },
    name: {
      type: String,
      default: undefined,
    },
    id: {
      type: String,
      default: undefined,
    },
    ariaDescribedby: {
      type: String,
      default: undefined,
    },
    block: {
      type: Boolean,
      default: true,
    },
    matchTriggerWidth: {
      type: Boolean,
      default: true,
    },
    /**
     * Seçenek panelinin sabit genişliği (ör. `'18rem'`). Özel `#trigger` ile açılan
     * ve seçenekleri açılınca yüklenen listelerde panel boş/iskelet hâliyle daralmaz.
     */
    width: {
      type: [String, Number],
      default: null,
    },
    scrollListThreshold: {
      type: Number,
      default: 6,
    },
    /** Sunucu tarafı arama — liste yerel filtrelenmez; `filter-change` yayınlanır */
    remoteFilter: {
      type: Boolean,
      default: false,
    },
    /** Liste açık durumu — `v-model:open` ile kontrol edilebilir */
    open: {
      type: Boolean,
      default: undefined,
    },
  },
  emits: ['update:modelValue', 'change', 'update:open', 'filter-change'],
  data() {
    const fallbackId = nextSelectId()
    const seq = fallbackId.slice('ui-select-'.length)
    return {
      fallbackId,
      fallbackListboxId: `ui-select-listbox-${seq}`,
      menuOpen: this.open ?? false,
      filterQuery: '',
      filterDebounceTimer: null,
      /** Klavye / fare vurgusu — `aria-activedescendant`; odak tetikleyicide veya aramada kalır. */
      activeIndex: -1,
    }
  },
  computed: {
    /**
     * Form satırındaki tüm kontroller aynı yükseklikte kalır; `ui-form-row primary`
     * yalnızca odak hedefidir, boyutu büyütmez. Büyük alan gerekiyorsa `size="lg"` verilir.
     */
    resolvedSize() {
      return resolveThemeControlSize(this.uiDefaults, this.size, { key: 'controlSize', defaultSize: 'md' })
    },
    /** Popover seçenekleri tetikleyici ile aynı boyutta (sm/md/lg). */
    optionButtonSize() {
      return this.resolvedSize
    },
    emptyStateSize() {
      return this.resolvedSize === 'lg' ? 'md' : 'sm'
    },
    listboxClass() {
      return this.resolvedSize !== 'md' ? `ui-select-listbox--${this.resolvedSize}` : undefined
    },
    filterInputClass() {
      return this.resolvedSize !== 'md' ? `ui-select-filter-input--${this.resolvedSize}` : undefined
    },
    rootClass() {
      const isInline = this.variant === 'inline'
      return cn(
        'ui-select',
        isInline && 'ui-select--inline',
        !isInline && this.block && 'ui-select--block w-full',
        !isInline && !this.block && 'w-auto shrink-0',
        this.resolvedSize !== 'md' && `ui-select--${this.resolvedSize}`,
        this.multiple && 'ui-select--multiple',
        this.isFilterable && 'ui-select--filterable',
        this.isDisabled && 'pointer-events-none opacity-50',
        this.$attrs.class,
      )
    },
    isFilterable() {
      return this.filterable || this.multiple
    },
    showPopoverHeader() {
      return this.isFilterable && !this.multiple
    },
    listboxRole() {
      return this.multiple ? 'listbox' : 'listbox'
    },
    resolvedMatchTriggerWidth() {
      if (this.variant === 'inline') return false
      return this.matchTriggerWidth
    },
    isDisabled() {
      return this.disabled
    },
    resolvedId() {
      if (this.id != null && this.id !== '') {
        return this.id
      }
      return this.formFieldId || this.fallbackId
    },
    activeOptionId() {
      return this.activeIndex >= 0 && this.activeIndex < this.filteredOptions.length
        ? this.optionId(this.activeIndex)
        : undefined
    },
    listboxId() {
      const id = this.id || this.formFieldId
      if (id) return `${id}-listbox`
      return this.fallbackListboxId
    },
    resolvedPlaceholder() {
      if (this.placeholder !== undefined && this.placeholder !== null) {
        return this.placeholder
      }
      if (typeof this.$t === 'function') {
        return this.$t('ui.select.placeholder')
      }
      return 'Seçiniz'
    },
    normalizedOptions() {
      const ph = this.resolvedPlaceholder
      return (this.options || [])
        .map((o) => {
          if (o != null && typeof o === 'object' && 'value' in o && 'label' in o) {
            return { ...o, value: o.value, label: o.label }
          }
          return { value: o, label: String(o) }
        })
        .filter((o) => {
          if (o.value === '' || o.value == null) return false
          const label = String(o.label)
          const value = String(o.value)
          return label !== ph && value !== ph
        })
    },
    filteredOptions() {
      if (!this.isFilterable || this.remoteFilter) {
        return this.normalizedOptions
      }
      const q = this.normalizeFilter(this.filterQuery)
      if (!q) {
        return this.normalizedOptions
      }
      return this.normalizedOptions.filter(
        (o) =>
          this.normalizeFilter(o.label).includes(q)
          || this.normalizeFilter(String(o.value)).includes(q)
          || this.normalizeFilter(o.description || '').includes(q)
          || this.normalizeFilter(o.badge || '').includes(q),
      )
    },
    selectedValues() {
      if (!this.multiple) return []
      if (!Array.isArray(this.modelValue)) return []
      return this.modelValue.filter((v) => v !== '' && v != null)
    },
    stringValue() {
      if (this.multiple) return ''
      if (this.modelValue === '' || this.modelValue == null) {
        return ''
      }
      return String(this.modelValue)
    },
    hiddenFieldValue() {
      if (this.multiple) {
        return this.selectedValues.map((v) => String(v)).join(',')
      }
      return this.stringValue
    },
    isPlaceholderDisplay() {
      if (this.multiple) return false
      return this.stringValue === ''
    },
    displayLabel() {
      if (this.isPlaceholderDisplay) {
        return this.resolvedPlaceholder
      }
      const m = this.normalizedOptions.find((o) => String(o.value) === this.stringValue)
      return m ? m.label : this.stringValue
    },
    selectedDisplayStyle() {
      if (this.multiple || this.isPlaceholderDisplay) return undefined
      const opt = this.normalizedOptions.find((o) => String(o.value) === this.stringValue)
      return this.optionDisplayStyle(opt)
    },
    multipleInputPlaceholder() {
      if (this.selectedValues.length > 0) {
        return ''
      }
      return this.resolvedPlaceholder
    },
    showClearButton() {
      if (this.isDisabled) return false
      if (this.multiple) {
        return this.clearable && this.selectedValues.length > 0
      }
      return this.clearable && this.stringValue !== ''
    },
    clearAriaLabel() {
      if (typeof this.$t === 'function') {
        return this.$t('ui.select.clear')
      }
      return 'Clear selection'
    },
    resolvedFilterPlaceholder() {
      if (this.filterPlaceholder) return this.filterPlaceholder
      if (typeof this.$t === 'function') {
        return this.$t('ui.select.filterPlaceholder')
      }
      return 'Search…'
    },
    noResultsText() {
      if (typeof this.$t === 'function') {
        return this.$t('ui.select.noResults')
      }
      return 'No results'
    },
    emptyOptionsText() {
      if (typeof this.$t === 'function') {
        return this.$t('ui.select.empty')
      }
      return 'No options'
    },
    resolvedLoadingLabel() {
      if (typeof this.$t === 'function') {
        return this.$t('ui.select.loading')
      }
      return 'Loading…'
    },
    triggerPassthrough() {
      const skip = new Set(['class', 'style', 'id', 'disabled', 'name'])
      const out = {}
      for (const [key, val] of Object.entries(this.$attrs)) {
        if (!skip.has(key)) {
          out[key] = val
        }
      }
      return out
    },
    optionCount() {
      return this.normalizedOptions.length
    },
    useScrollListMode() {
      if (this.isFilterable) return true
      return this.optionCount > this.scrollListThreshold
    },
    alignSelectedToTrigger() {
      return !this.useScrollListMode
    },
  },
  watch: {
    filterQuery(q) {
      this.activeIndex = this.filteredOptions.length ? 0 : -1
      if (
        this.multiple
        && !this.menuOpen
        && !this.isDisabled
        && String(q ?? '').length > 0
      ) {
        this.menuOpen = true
      }
      if (!this.remoteFilter) return
      if (this.filterDebounceTimer) {
        clearTimeout(this.filterDebounceTimer)
      }
      this.filterDebounceTimer = setTimeout(() => {
        this.$emit('filter-change', String(q ?? '').trim())
      }, 300)
    },
    open(value) {
      if (value != null && value !== this.menuOpen) this.menuOpen = value
    },
    menuOpen(open) {
      if (open !== this.open) this.$emit('update:open', open)
      if (!open) {
        if (this.filterDebounceTimer) {
          clearTimeout(this.filterDebounceTimer)
          this.filterDebounceTimer = null
        }
        this.filterQuery = ''
        this.activeIndex = -1
        return
      }
      this.activeIndex = this.initialActiveIndex()
      this.$nextTick(() => {
        if (this.isFilterable) {
          this.focusSearch()
        }
        if (this.useScrollListMode || this.isListboxScrollable()) {
          this.scrollSelectedIntoView()
        }
      })
    },
  },
  methods: {
    /**
     * Tetikleyici öznitelikleri. Tek seçim: `button` combobox tetikleyicisi. Çoklu seçim: kapsayıcı
     * `div` — içinde etiket silme düğmeleri ve arama input'u olduğundan `button` içinde iç içe
     * etkileşim oluşuyordu (axe nested-interactive). Aramalı çoklu seçimde combobox rolü input'tadır;
     * aramasızda kapsayıcı odaklanabilir combobox olur.
     */
    triggerAttrs(open) {
      const aria = {
        'aria-expanded': open ? 'true' : 'false',
        'aria-haspopup': this.listboxRole,
        'aria-controls': open ? this.listboxId : undefined,
        'aria-activedescendant': open ? this.activeOptionId : undefined,
        'aria-describedby': this.formFieldDescribedBy(this.ariaDescribedby),
        'aria-invalid': this.formFieldInvalid,
      }
      if (!this.multiple) {
        return { type: 'button', id: this.resolvedId, disabled: this.isDisabled, ...aria, ...this.triggerPassthrough }
      }
      if (this.isFilterable) {
        return { 'aria-disabled': this.isDisabled ? 'true' : undefined }
      }
      return {
        id: this.resolvedId,
        role: 'combobox',
        tabindex: this.isDisabled ? -1 : 0,
        'aria-disabled': this.isDisabled ? 'true' : undefined,
        ...aria,
        ...this.triggerPassthrough,
      }
    },
    normalizeFilter(value) {
      return String(value ?? '')
        .trim()
        .toLocaleLowerCase()
    },
    focusSearch() {
      const el = this.multiple ? this.$refs.searchInput : this.$refs.filterInput
      if (el && typeof el.focus === 'function') {
        el.focus()
        el.select?.()
      }
    },
    onSearchInputActivate() {
      if (this.isDisabled) return
      if (!this.menuOpen) {
        this.menuOpen = true
      }
    },
    onTriggerClick(toggle) {
      if (this.isDisabled) return
      toggle()
      if (this.multiple && this.menuOpen) {
        this.$nextTick(() => this.focusSearch())
      }
    },
    isListboxScrollable() {
      const listbox = this.$refs.listbox
      if (!listbox) return false
      return listbox.scrollHeight > listbox.clientHeight + 2
    },
    scrollSelectedIntoView() {
      const listbox = this.$refs.listbox
      if (!listbox) return
      const selected = listbox.querySelector('[role="option"][aria-selected="true"]')
      if (!selected) return
      selected.scrollIntoView({ block: 'nearest', inline: 'nearest' })
    },
    labelForValue(val) {
      const m = this.normalizedOptions.find((o) => String(o.value) === String(val))
      return m ? m.label : String(val)
    },
    optionDisplayStyle(opt) {
      if (!opt || typeof opt !== 'object') return undefined
      if (opt.style && typeof opt.style === 'object') return opt.style
      if (typeof opt.fontFamily === 'string' && opt.fontFamily.trim()) {
        return { fontFamily: opt.fontFamily.trim() }
      }
      return undefined
    },
    isSelected(opt) {
      if (this.multiple) {
        return this.selectedValues.some((v) => String(v) === String(opt.value))
      }
      return String(opt.value) === this.stringValue
    },
    pick(opt, close) {
      if (this.multiple) {
        this.toggleValue(opt)
        this.$nextTick(() => this.focusSearch())
        return
      }
      this.$emit('update:modelValue', opt.value)
      this.$emit('change', { type: 'change', target: { value: String(opt.value) } })
      this.menuOpen = false
      close()
    },
    toggleValue(opt) {
      const cur = Array.isArray(this.modelValue) ? [...this.modelValue] : []
      const idx = cur.findIndex((v) => String(v) === String(opt.value))
      if (idx >= 0) {
        cur.splice(idx, 1)
      } else {
        cur.push(opt.value)
      }
      this.$emit('update:modelValue', cur)
      this.$emit('change', { type: 'change', target: { value: cur.map(String).join(',') } })
    },
    removeValue(val) {
      if (!this.multiple) return
      const cur = Array.isArray(this.modelValue) ? [...this.modelValue] : []
      const idx = cur.findIndex((v) => String(v) === String(val))
      if (idx < 0) return
      cur.splice(idx, 1)
      this.$emit('update:modelValue', cur)
      this.$emit('change', { type: 'change', target: { value: cur.map(String).join(',') } })
    },
    clearSelection() {
      if (this.multiple) {
        this.$emit('update:modelValue', [])
        this.$emit('change', { type: 'change', target: { value: '' } })
      } else {
        this.$emit('update:modelValue', '')
        this.$emit('change', { type: 'change', target: { value: '' } })
      }
      this.menuOpen = false
    },
    optionId(i) {
      return `${this.listboxId}-option-${i}`
    },
    /** Açılışta seçili seçenek (yoksa ilki) vurgulanır. */
    initialActiveIndex() {
      if (!this.filteredOptions.length) return -1
      const i = this.filteredOptions.findIndex((o) => this.isSelected(o))
      return i >= 0 ? i : 0
    },
    moveActive(next) {
      const n = this.filteredOptions.length
      if (!n) return
      this.activeIndex = Math.max(0, Math.min(n - 1, next))
      this.$nextTick(() => {
        const el = this.activeOptionId && document.getElementById(this.activeOptionId)
        el?.scrollIntoView?.({ block: 'nearest', inline: 'nearest' })
      })
    },
    /**
     * Liste gezinmesi — ↑ ↓ Home End; tetikleyici, panel araması ve çoklu arama aynı yolu kullanır.
     * @returns {boolean} tuş işlendi mi
     */
    handleListKey(e) {
      const page = 8
      const keys = {
        ArrowDown: () => this.activeIndex + 1,
        ArrowUp: () => this.activeIndex - 1,
        Home: () => 0,
        End: () => this.filteredOptions.length - 1,
        PageDown: () => this.activeIndex + page,
        PageUp: () => this.activeIndex - page,
      }
      if (!keys[e.key]) return false
      e.preventDefault()
      if (!this.menuOpen) {
        if (e.key === 'ArrowDown' || e.key === 'ArrowUp') this.menuOpen = true
        return true
      }
      this.moveActive(keys[e.key]())
      return true
    },
    /** Vurgulanan seçeneği seçer; tek seçimde odak tetikleyiciye döner (panel araması kapanır). */
    pickActive(close) {
      const opt = this.filteredOptions[this.activeIndex]
      if (!opt) return false
      this.pick(opt, close)
      if (!this.multiple) {
        this.$nextTick(() => this.$el?.querySelector?.('.ui-select-field')?.focus?.())
      }
      return true
    },
    onTriggerKeydown(e, toggle) {
      if (this.isDisabled) return
      if (this.multiple) {
        // Aramalı çoklu seçimde tuşlar input'ta işlenir; aramasızda kapsayıcı combobox'tır.
        if (this.isFilterable || e.target !== e.currentTarget) return
        if (this.handleListKey(e)) return
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault()
          if (!this.menuOpen) toggle()
          else this.pickActive(() => {})
        }
        return
      }
      if (this.handleListKey(e)) return
      if (this.menuOpen && (e.key === 'Enter' || e.key === ' ')) {
        e.preventDefault()
        this.pickActive(() => {})
      }
    },
    onFilterKeydown(e, close) {
      if (this.handleListKey(e)) return
      if (e.key === 'Enter') {
        e.preventDefault()
        if (!this.pickActive(close)) this.pickFirstFiltered(close)
        return
      }
      if (e.key === 'Escape') {
        e.preventDefault()
        close()
        this.$nextTick(() => this.$el?.querySelector?.('.ui-select-field')?.focus?.())
      }
    },
    pickFirstFiltered(close) {
      if (this.filteredOptions.length === 0) return
      const first = this.filteredOptions[0]
      if (this.multiple) {
        if (!this.isSelected(first)) {
          this.toggleValue(first)
        }
        return
      }
      this.pick(first, close)
    },
    onSearchKeydown(e) {
      if (this.handleListKey(e)) return
      if (e.key === 'Enter') {
        e.preventDefault()
        if (!this.menuOpen) {
          this.menuOpen = true
          return
        }
        if (!this.pickActive(() => {})) this.pickFirstFiltered(() => {})
        return
      }
      if (e.key === 'Escape') {
        e.preventDefault()
        this.menuOpen = false
        return
      }
      if (
        this.multiple &&
        e.key === 'Backspace' &&
        !this.filterQuery &&
        this.selectedValues.length > 0
      ) {
        e.preventDefault()
        const last = this.selectedValues[this.selectedValues.length - 1]
        this.removeValue(last)
      }
    },
  },
}
</script>
